"""
Generator for MLUA Conversational NLU Dataset (Exactly 500 Examples).
Generates:
  backend/nlp/data/conversational_qa_dataset.jsonl
  backend/nlp/data/conversational_qa_dataset.csv

Strict Category Distribution (Exact 500):
  1.  Basic case questions: 60 (EN: 30, HINGLISH: 30)
  2.  Lesion location: 45 (EN: 22, HINGLISH: 23)
  3.  Tooth identification: 30 (EN: 15, HINGLISH: 15)
  4.  Stage/severity: 50 (EN: 25, HINGLISH: 25)
  5.  Segmentation findings: 35 (EN: 17, HINGLISH: 18)
  6.  Probability/model output: 25 (EN: 13, HINGLISH: 12)
  7.  Coordinates/area: 25 (EN: 12, HINGLISH: 13)
  8.  MLUA technical basics: 35 (EN: 18, HINGLISH: 17)
  9.  Report explanation: 30 (EN: 15, HINGLISH: 15)
  10. Reasoning/follow-up questions: 45 (EN: 22, HINGLISH: 23)
  11. Clarification/confusion: 25 (EN: 13, HINGLISH: 12)
  12. Medical safety: 35 (EN: 17, HINGLISH: 18)
  13. Language switching: 30 (EN: 15, HINGLISH: 15)
  14. Greetings/general conversation: 15 (EN: 8, HINGLISH: 7)
  15. Help/reset/capabilities: 15 (EN: 8, HINGLISH: 7)
  TOTAL = 500

Strict Language Distribution (Exact 500):
  English: 250
  Hinglish: 250
  TOTAL = 500
"""

import json
import csv
import os

DATA_ENTRIES = []

def add_entry(text, language, intent, emotion, expected_scope, case_required, safety_level, difficulty, category, expected_behavior):
    global DATA_ENTRIES
    idx = len(DATA_ENTRIES) + 1
    DATA_ENTRIES.append({
        'id': f'CONV_{idx:03d}',
        'text': text,
        'language': language,
        'intent': intent,
        'emotion': emotion,
        'expected_scope': expected_scope,
        'case_required': case_required,
        'safety_level': safety_level,
        'difficulty': difficulty,
        'category': category,
        'expected_behavior': expected_behavior
    })


