def save_datasets():
    os.makedirs('backend/nlp/data', exist_ok=True)
    jsonl_path = 'backend/nlp/data/conversational_qa_dataset.jsonl'
    csv_path = 'backend/nlp/data/conversational_qa_dataset.csv'

    print(f'Total entries generated: {len(DATA_ENTRIES)}')
    assert len(DATA_ENTRIES) == 500, f'Expected 500 entries, got {len(DATA_ENTRIES)}'

    # Save JSONL
    with open(jsonl_path, 'w', encoding='utf-8') as f:
        for entry in DATA_ENTRIES:
            f.write(json.dumps(entry, ensure_ascii=False) + '\n')

    # Save CSV
    fieldnames = [
        'id', 'text', 'language', 'intent', 'emotion',
        'expected_scope', 'case_required', 'safety_level', 'difficulty', 'category',
        'expected_behavior'
    ]
    with open(csv_path, 'w', encoding='utf-8', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        for entry in DATA_ENTRIES:
            writer.writerow(entry)

    print(f'Successfully saved {jsonl_path} and {csv_path}')

if __name__ == '__main__':
    save_datasets()
